from flask import Flask, Response
import time, json

app = Flask(__name__)

@app.get('/stream')
def stream():
    def gen():
        while True:
            payload = json.dumps({'ts': time.time()})
            yield f'data: {payload}\n\n'
            time.sleep({{interval_sec}})
    return Response(gen(), mimetype='text/event-stream')
